const K='meeting-points-admin-drafts',read=()=>JSON.parse(localStorage.getItem(K)||'[]'),safe=s=>String(s||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const scores=(v='')=>`<option value="">--</option>${Array.from({length:11},(_,i)=>`<option ${String(v)===String(i)?'selected':''}>${i}</option>`).join('')}`;
const placement=(value='none')=>`<fieldset class="admin-placement"><legend>Onde entra?</legend>${[['none','Arquivo','Apenas na coleção'],['frequency','Na frequência','Destaque principal'],['radar','Top 5','No meu radar']].map(([v,t,d])=>`<label><input type="radio" name="placement" value="${v}" ${value===v?'checked':''}><span><strong>${t}</strong><small>${d}</small></span></label>`).join('')}<p>Só notas 9 ou 10 podem virar destaque.</p></fieldset>`;
const emptyRecord={id:'',title:'',artist:'',score:'',genre:'',type:'Álbum',label:'',url:'',listenLabel:'Ouvir',catalogDescription:'',cover:'',coverOriginal:'',backCover:'',backCoverOriginal:'',artistPhoto:{},review:[]};
export function adminPage(){const items=read();return `<section class="admin-shell"><header class="admin-intro"><a href="./#inicio">← meeting.points</a><span class="eyebrow">OFICINA PRIVADA</span><h1>Central editorial.</h1><p>Publique, revise capas e mantenha o arquivo vivo.</p><div class="admin-steps"><button class="active" type="button" data-mode="new">Nova review</button><button type="button" data-mode="edit">Editar arquivo</button></div></header><div class="admin-grid"><form class="admin-form" id="admin-form"><input type="hidden" name="id"><section><div class="admin-score-head"><h2 data-form-title>Nova review</h2><label>Nota<select name="score" required>${scores()}</select><span>/ 10</span></label></div><div class="admin-row"><label>Nome do álbum<input name="title" required placeholder="Ex.: Untrue"></label><label>Artista<input name="artist" required placeholder="Ex.: Burial"></label></div><div class="admin-row optional-fields"><label>Gênero<input name="genre" placeholder="Preenchido automático, editável depois"></label><label>Formato<input name="type" placeholder="Álbum, EP, mixtape..."></label></div></section><section><h2>Texto</h2><label>Primeiras impressões<textarea name="review" required rows="4" placeholder="Para nova review, escreva a abertura. Para edição, o texto completo aparece aqui em parágrafos."></textarea></label><label class="new-only">Review completa<textarea name="body" rows="10" placeholder="Escreva ou cole o texto completo..."></textarea></label></section>${placement()}<section class="manual-fields"><h2>Ajustes manuais</h2><div class="admin-row"><label>Capa<input name="cover" placeholder="URL da capa em alta"></label><label>Capa original<input name="coverOriginal" placeholder="URL original, se diferente"></label></div><div class="admin-row"><label>Contracapa<input name="backCover" placeholder="URL da contracapa"></label><label>Contracapa original<input name="backCoverOriginal" placeholder="URL original da contracapa"></label></div><div class="admin-row"><label>Foto do artista<input name="artistPhotoSrc" placeholder="URL da foto"></label><label>Crédito da foto<input name="artistPhotoCredit" placeholder="Ex.: Deezer, divulgação, fotógrafo"></label></div><div class="admin-row optional-fields"><label>Link para ouvir<input name="url" placeholder="Apple, Deezer, Bandcamp..."></label><label>Texto do botão<input name="listenLabel" placeholder="Ouvir no Apple Music"></label></div><label>Sobre o lançamento<textarea name="catalogDescription" rows="3" placeholder="Descrição curta da ficha técnica"></textarea></label></section><div class="admin-auto"><strong>Preenchimento automático</strong><p>Em novas reviews, a central busca capa, faixas, duração, links e ficha. Em edições, você corrige só o que quiser e o resto permanece.</p></div><div class="admin-actions"><button class="solid" type="submit">Salvar rascunho</button><button class="publish-current" type="button">Buscar dados e publicar ↗</button><button class="save-edit" type="button" hidden>Salvar edição ↗</button></div><p class="admin-status" role="status"></p></form><aside class="admin-drafts"><div class="section-head"><h2 data-side-title>Rascunhos</h2><span data-side-count>${items.length}</span></div><div class="admin-list" data-list>${items.map((d,i)=>draft(d,i)).join('')||'<div class="admin-empty"><span>○</span><p>Seu próximo disco começa aqui.</p></div>'}</div></aside></div></section>`}
const draft=(d,i)=>`<article class="draft-card"><button data-draft="${i}"><strong>${safe(d.title)||'Sem título'}</strong><span>${safe(d.artist)||'Artista'}</span></button><button data-publish="${i}">Completar e publicar ↗</button></article>`;
const reviewItem=a=>`<article class="draft-card"><button data-edit="${safe(a.id)}"><strong>${safe(a.title)}</strong><span>${safe(a.artist)} · ${safe(a.score)}/10</span></button><a href="./#album/${safe(a.id)}">Abrir ↗</a></article>`;
async function publish(d,status,button){if(!d.title||!d.artist||!d.review||!d.body||d.score==='')return status.textContent='Preencha álbum, artista, nota e os dois textos.';if(+d.score<9)d.placement='none';button.disabled=true;status.textContent='Buscando capa, perfil, faixas e dados oficiais...';try{const r=await fetch('/api/admin/reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}),x=await r.json();if(!r.ok)throw Error(x.error||'Não foi possível publicar.');status.innerHTML=`Review publicada. <a href="./#album/${x.id}">Abrir no site ↗</a>`;button.textContent='Publicado ✓'}catch(e){status.textContent=e.message;button.disabled=false}}
async function saveEdit(d,status,button){if(!d.id)return status.textContent='Escolha uma review para editar.';button.disabled=true;status.textContent='Salvando ajustes...';try{const r=await fetch('/api/admin/reviews',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}),x=await r.json();if(!r.ok)throw Error(x.error||'Não foi possível salvar.');status.innerHTML=`Edição salva. <a href="./#album/${x.id}">Abrir review ↗</a>`;button.disabled=false}catch(e){status.textContent=e.message;button.disabled=false}}
const fill=(f,a)=>{const p={...emptyRecord,...a},photo=p.artistPhoto||{};f.elements.id.value=p.id||'';f.elements.title.value=p.title||'';f.elements.artist.value=p.artist||'';f.elements.score.value=p.score??'';f.elements.genre.value=p.genre||'';f.elements.type.value=p.type||'';f.elements.review.value=(p.review||[]).join('\n\n');f.elements.body.value='';f.elements.cover.value=p.cover||'';f.elements.coverOriginal.value=p.coverOriginal||'';f.elements.backCover.value=p.backCover||'';f.elements.backCoverOriginal.value=p.backCoverOriginal||'';f.elements.artistPhotoSrc.value=photo.src||'';f.elements.artistPhotoCredit.value=photo.credit||'';f.elements.url.value=p.url||'';f.elements.listenLabel.value=p.listenLabel||'';f.elements.catalogDescription.value=p.catalogDescription||'';if(f.elements.placement)f.elements.placement.value=p.placement||'none'};
export function bindAdmin(root){const f=root.querySelector('#admin-form'),status=root.querySelector('.admin-status'),list=root.querySelector('[data-list]'),sideTitle=root.querySelector('[data-side-title]'),sideCount=root.querySelector('[data-side-count]'),data=()=>Object.fromEntries(new FormData(f));let catalog=[];const setMode=async mode=>{root.dataset.mode=mode;root.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));root.querySelector('[data-form-title]').textContent=mode==='edit'?'Editar review':'Nova review';root.querySelector('.publish-current').hidden=mode==='edit';root.querySelector('.save-edit').hidden=mode!=='edit';root.querySelector('.new-only').hidden=mode==='edit';f.querySelector('[type=submit]').hidden=mode==='edit';status.textContent='';if(mode==='edit'){sideTitle.textContent='Reviews';list.innerHTML='<div class="admin-empty"><p>Carregando arquivo...</p></div>';catalog=await fetch('/api/admin/reviews').then(r=>r.json());sideCount.textContent=catalog.length;list.innerHTML=catalog.map(reviewItem).join('');}else{const items=read();sideTitle.textContent='Rascunhos';sideCount.textContent=items.length;list.innerHTML=items.map((d,i)=>draft(d,i)).join('')||'<div class="admin-empty"><span>○</span><p>Seu próximo disco começa aqui.</p></div>';fill(f,emptyRecord);}};root.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));f.onsubmit=e=>{e.preventDefault();if(!f.reportValidity())return;const d={...data(),id:'draft-'+Date.now()};localStorage.setItem(K,JSON.stringify([d,...read()]));status.textContent='Rascunho salvo.';setTimeout(()=>location.reload(),350)};root.querySelector('.publish-current').onclick=e=>{if(f.reportValidity())publish(data(),status,e.currentTarget)};root.querySelector('.save-edit').onclick=e=>saveEdit(data(),status,e.currentTarget);list.addEventListener('click',e=>{const draftButton=e.target.closest('[data-draft]'),publishButton=e.target.closest('[data-publish]'),editButton=e.target.closest('[data-edit]');if(draftButton){fill(f,read()[+draftButton.dataset.draft]);}if(publishButton)publish(read()[+publishButton.dataset.publish],status,publishButton);if(editButton){const item=catalog.find(a=>a.id===editButton.dataset.edit);if(item){status.textContent='Carregando review completa...';fetch('/catalog.json').then(r=>r.json()).then(all=>{fill(f,all.find(a=>a.id===item.id)||item);status.textContent='Review carregada para edição.';});}}});setMode('new')}
